package com.kmgtechnologies.ecommerce.media;

import com.kmgtechnologies.ecommerce.exception.StorageUnavailableException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import software.amazon.awssdk.core.exception.SdkException;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.services.s3.S3Client;

/**
 * Objects of the media bucket. Keys are generated by the application ({@link MediaFiles}); objects are immutable
 * (a new image is a new key), so browsers and proxies may cache them for a long time.
 */
@Component
public class MediaStorage {

    static final String CACHE_CONTROL = "public, max-age=31536000, immutable";

    private static final Logger log = LoggerFactory.getLogger(MediaStorage.class);

    private final S3Client s3;
    private final String bucket;

    public MediaStorage(S3Client s3, MediaProperties properties) {
        this.s3 = s3;
        this.bucket = properties.bucket();
    }

    public void put(String key, byte[] content, String contentType) {
        try {
            s3.putObject(request -> request.bucket(bucket).key(key)
                            .contentType(contentType)
                            .cacheControl(CACHE_CONTROL),
                    RequestBody.fromBytes(content));
        } catch (SdkException e) {
            throw new StorageUnavailableException("The media storage is unavailable, please retry later", e);
        }
    }

    /**
     * Best effort: called once the database no longer references the object. A failure leaves an orphan object
     * (logged with its key), never a broken image.
     */
    public void delete(String key) {
        try {
            s3.deleteObject(request -> request.bucket(bucket).key(key));
        } catch (SdkException e) {
            log.warn("Media object {} not deleted: {}", key, e.getMessage());
        }
    }
}
